-- Generated from source CSV files by scripts/export_sql.py.
-- Synthetic operational records only; ground_truth is deliberately excluded.
PRAGMA foreign_keys = ON;
BEGIN TRANSACTION;
CREATE TABLE batch_machine (
	batch_machine_id VARCHAR NOT NULL, 
	batch_id VARCHAR NOT NULL, 
	machine_id VARCHAR NOT NULL, 
	output_units INTEGER NOT NULL, 
	PRIMARY KEY (batch_machine_id), 
	FOREIGN KEY(batch_id) REFERENCES production_batches (batch_id), 
	FOREIGN KEY(machine_id) REFERENCES machines (machine_id)
);
CREATE TABLE energy_readings (
	row_id VARCHAR NOT NULL, 
	reading_id VARCHAR NOT NULL, 
	meter_id VARCHAR NOT NULL, 
	machine_id VARCHAR, 
	timestamp_utc VARCHAR NOT NULL, 
	energy_kwh FLOAT NOT NULL, 
	avg_power_kw FLOAT NOT NULL, 
	unit VARCHAR NOT NULL, 
	state VARCHAR NOT NULL, 
	shift_id VARCHAR, 
	PRIMARY KEY (row_id), 
	FOREIGN KEY(meter_id) REFERENCES meters (meter_id), 
	FOREIGN KEY(machine_id) REFERENCES machines (machine_id), 
	FOREIGN KEY(shift_id) REFERENCES shifts (shift_id)
);
CREATE TABLE machines (
	machine_id VARCHAR NOT NULL, 
	plant_id VARCHAR NOT NULL, 
	machine_name VARCHAR NOT NULL, 
	machine_type VARCHAR NOT NULL, 
	rated_power_kw FLOAT NOT NULL, 
	status VARCHAR NOT NULL, 
	PRIMARY KEY (machine_id), 
	FOREIGN KEY(plant_id) REFERENCES plants (plant_id)
);
CREATE TABLE maintenance_events (
	event_id VARCHAR NOT NULL, 
	machine_id VARCHAR NOT NULL, 
	event_type VARCHAR NOT NULL, 
	start_utc VARCHAR NOT NULL, 
	end_utc VARCHAR, 
	status VARCHAR NOT NULL, 
	notes TEXT NOT NULL, 
	PRIMARY KEY (event_id), 
	FOREIGN KEY(machine_id) REFERENCES machines (machine_id)
);
CREATE TABLE meter_machine (
	assignment_id VARCHAR NOT NULL, 
	meter_id VARCHAR NOT NULL, 
	machine_id VARCHAR NOT NULL, 
	effective_from VARCHAR NOT NULL, 
	effective_to VARCHAR, 
	PRIMARY KEY (assignment_id), 
	FOREIGN KEY(meter_id) REFERENCES meters (meter_id), 
	FOREIGN KEY(machine_id) REFERENCES machines (machine_id)
);
CREATE TABLE meter_register_totals (
	meter_id VARCHAR NOT NULL, 
	register_total_kwh FLOAT NOT NULL, 
	PRIMARY KEY (meter_id), 
	FOREIGN KEY(meter_id) REFERENCES meters (meter_id)
);
CREATE TABLE meters (
	meter_id VARCHAR NOT NULL, 
	plant_id VARCHAR NOT NULL, 
	meter_name VARCHAR NOT NULL, 
	unit VARCHAR NOT NULL, 
	cadence_minutes INTEGER NOT NULL, 
	status VARCHAR NOT NULL, 
	PRIMARY KEY (meter_id), 
	FOREIGN KEY(plant_id) REFERENCES plants (plant_id)
);
CREATE TABLE plants (
	plant_id VARCHAR NOT NULL, 
	name VARCHAR NOT NULL, 
	location VARCHAR NOT NULL, 
	timezone VARCHAR NOT NULL, 
	status VARCHAR NOT NULL, 
	PRIMARY KEY (plant_id)
);
CREATE TABLE production_batches (
	batch_id VARCHAR NOT NULL, 
	plant_id VARCHAR NOT NULL, 
	shift_id VARCHAR, 
	start_utc VARCHAR NOT NULL, 
	end_utc VARCHAR NOT NULL, 
	planned_output_units INTEGER NOT NULL, 
	actual_output_units INTEGER NOT NULL, 
	status VARCHAR NOT NULL, 
	PRIMARY KEY (batch_id), 
	FOREIGN KEY(plant_id) REFERENCES plants (plant_id), 
	FOREIGN KEY(shift_id) REFERENCES shifts (shift_id)
);
CREATE TABLE recommendations (
	recommendation_id VARCHAR NOT NULL, 
	machine_id VARCHAR NOT NULL, 
	created_utc VARCHAR NOT NULL, 
	reason TEXT NOT NULL, 
	baseline_kwh FLOAT NOT NULL, 
	expected_savings_kwh FLOAT NOT NULL, 
	expected_savings_inr FLOAT NOT NULL, 
	priority VARCHAR NOT NULL, 
	status VARCHAR NOT NULL, 
	PRIMARY KEY (recommendation_id), 
	FOREIGN KEY(machine_id) REFERENCES machines (machine_id)
);
CREATE TABLE shifts (
	shift_id VARCHAR NOT NULL, 
	plant_id VARCHAR NOT NULL, 
	shift_name VARCHAR NOT NULL, 
	start_time VARCHAR NOT NULL, 
	end_time VARCHAR NOT NULL, 
	effective_from VARCHAR NOT NULL, 
	effective_to VARCHAR, 
	PRIMARY KEY (shift_id), 
	FOREIGN KEY(plant_id) REFERENCES plants (plant_id)
);
CREATE TABLE state_events (
	state_event_id VARCHAR NOT NULL, 
	entity_type VARCHAR NOT NULL, 
	entity_id VARCHAR NOT NULL, 
	old_state VARCHAR, 
	new_state VARCHAR NOT NULL, 
	event_utc VARCHAR NOT NULL, 
	actor VARCHAR NOT NULL, 
	reason TEXT NOT NULL, 
	PRIMARY KEY (state_event_id)
);
CREATE TABLE tariffs (
	tariff_id VARCHAR NOT NULL, 
	plant_id VARCHAR NOT NULL, 
	tariff_name VARCHAR NOT NULL, 
	start_hour_utc INTEGER NOT NULL, 
	end_hour_utc INTEGER NOT NULL, 
	rate_inr_per_kwh FLOAT NOT NULL, 
	effective_from VARCHAR NOT NULL, 
	effective_to VARCHAR, 
	timezone VARCHAR NOT NULL, 
	PRIMARY KEY (tariff_id), 
	FOREIGN KEY(plant_id) REFERENCES plants (plant_id)
);
CREATE TABLE weather_observations (
	weather_id VARCHAR NOT NULL, 
	plant_id VARCHAR NOT NULL, 
	timestamp_utc VARCHAR NOT NULL, 
	temperature_c FLOAT NOT NULL, 
	humidity_pct FLOAT NOT NULL, 
	condition VARCHAR NOT NULL, 
	PRIMARY KEY (weather_id), 
	FOREIGN KEY(plant_id) REFERENCES plants (plant_id)
);
COMMIT;
